INSERT INTO poc_eq_quizzes (id, title, draw_count, pass_percent, max_attempts, cooldown_seconds, reward_xp) VALUES ('porque', 'Astronomia: a resposta e o porquê', 5, 70, NULL, 60, 100);
INSERT INTO poc_eq_questions (quiz_id, kind, prompt, content, answer, rationale) VALUES
('porque', 'twostep', 'O que causa as estações do ano na Terra?', '{"first": "single", "options": [{"id": "a", "text": "A distância entre a Terra e o Sol"}, {"id": "b", "text": "A inclinação do eixo da Terra"}, {"id": "c", "text": "As fases da Lua"}], "reasonPrompt": "Por que essa é a resposta certa?", "reasons": [{"id": "r1", "text": "Porque a Terra fica mais perto do Sol no verão"}, {"id": "r2", "text": "Porque cada hemisfério recebe a luz do Sol mais de frente em uma parte do ano"}, {"id": "r3", "text": "Porque a Lua bloqueia parte da luz do Sol no inverno"}], "halfCredit": false}', '{"option": "b", "reason": "r2"}', 'Em janeiro a Terra está no ponto mais perto do Sol, e é verão só no hemisfério sul: a distância não explica as estações, a inclinação explica.'),
('porque', 'twostep', 'Qual é o planeta mais quente do Sistema Solar?', '{"first": "single", "options": [{"id": "a", "text": "Mercúrio"}, {"id": "b", "text": "Vênus"}, {"id": "c", "text": "Marte"}], "reasonPrompt": "Por que essa é a resposta certa?", "reasons": [{"id": "r1", "text": "Porque é o planeta mais perto do Sol"}, {"id": "r2", "text": "Porque a atmosfera densa de gás carbônico prende o calor"}, {"id": "r3", "text": "Porque tem vulcões ativos na superfície inteira"}], "halfCredit": true}', '{"option": "b", "reason": "r2"}', 'Mercúrio fica mais perto do Sol, mas quase não tem atmosfera; o efeito estufa deixa Vênus acima de 460 °C.'),
('porque', 'twostep', 'A Lua tem luz própria.', '{"first": "truefalse", "reasonPrompt": "Por quê?", "reasons": [{"id": "r1", "text": "Porque a Lua reflete a luz do Sol, e por isso tem fases"}, {"id": "r2", "text": "Porque a Lua só brilha na fase cheia"}, {"id": "r3", "text": "Porque a luz da Lua vem das cidades da Terra"}], "halfCredit": false}', '{"value": false, "reason": "r1"}', 'As fases mostram quanto da metade iluminada pelo Sol nós vemos daqui.'),
('porque', 'twostep', 'Um ano-luz é uma medida de tempo.', '{"first": "truefalse", "reasonPrompt": "Por quê?", "reasons": [{"id": "r1", "text": "Porque mede quanto tempo a luz leva para cruzar o Sistema Solar"}, {"id": "r2", "text": "Porque mede a distância que a luz percorre em um ano"}, {"id": "r3", "text": "Porque mede a idade das estrelas"}], "halfCredit": true}', '{"value": false, "reason": "r2"}', 'São cerca de 9,46 trilhões de km: o nome tem "ano", mas é uma distância.'),
('porque', 'twostep', 'Quanto tempo a Lua leva para girar uma vez em torno do próprio eixo?', '{"first": "single", "options": [{"id": "a", "text": "1 dia"}, {"id": "b", "text": "Cerca de 27 dias"}, {"id": "c", "text": "1 ano"}], "reasonPrompt": "Por que essa é a resposta certa?", "reasons": [{"id": "r1", "text": "Porque o giro tem o mesmo tempo da volta em torno da Terra, e por isso vemos sempre a mesma face"}, {"id": "r2", "text": "Porque a Lua quase não gira"}, {"id": "r3", "text": "Porque a gravidade do Sol freia a Lua todo mês"}], "halfCredit": false}', '{"option": "b", "reason": "r1"}', 'É a rotação sincronizada: as marés da Terra sobre a Lua igualaram os dois tempos ao longo de bilhões de anos.'),
('porque', 'twostep', 'Na Estação Espacial, os astronautas flutuam porque lá não há gravidade.', '{"first": "truefalse", "reasonPrompt": "Por quê?", "reasons": [{"id": "r1", "text": "Porque a Estação está em queda livre em volta da Terra, e tudo cai junto"}, {"id": "r2", "text": "Porque a Estação fica acima da atmosfera, onde a gravidade acaba"}, {"id": "r3", "text": "Porque o Sol puxa a Estação para o lado oposto ao da Terra"}], "halfCredit": false}', '{"value": false, "reason": "r1"}', 'A 400 km de altura, a gravidade ainda é cerca de 90% da que sentimos no chão; a sensação de flutuar vem da queda livre.'),
('porque', 'twostep', 'Qual destes corpos causa as maiores marés nos oceanos da Terra?', '{"first": "single", "options": [{"id": "a", "text": "A Lua"}, {"id": "b", "text": "O Sol"}, {"id": "c", "text": "Júpiter"}], "reasonPrompt": "Por que essa é a resposta certa?", "reasons": [{"id": "r1", "text": "Porque a Lua tem mais massa que o Sol"}, {"id": "r2", "text": "Porque a Lua está muito mais perto, e a maré vem da diferença da atração de um lado ao outro da Terra"}, {"id": "r3", "text": "Porque a Lua também tem oceanos"}], "halfCredit": true}', '{"option": "a", "reason": "r2"}', 'O Sol atrai mais a Terra, mas a maré vem da diferença da atração entre os dois lados do planeta, e essa diferença cai muito com a distância.'),
('porque', 'single', 'Qual é o maior planeta do Sistema Solar?', '{"options": [{"id": "a", "text": "Saturno"}, {"id": "b", "text": "Júpiter"}, {"id": "c", "text": "Netuno"}, {"id": "d", "text": "Terra"}]}', '{"option": "b"}', NULL),
('porque', 'truefalse', 'Plutão é classificado hoje como um planeta anão.', '{}', '{"value": true}', 'Desde 2006, a União Astronômica Internacional o classifica como planeta anão.'),
('porque', 'ordering', 'Ponha os planetas em ordem, do mais perto ao mais longe do Sol.', '{"items": [{"id": "me", "text": "Mercúrio"}, {"id": "ve", "text": "Vênus"}, {"id": "te", "text": "Terra"}, {"id": "ma", "text": "Marte"}]}', '{"order": ["me", "ve", "te", "ma"]}', NULL);
