-- PoC da US59: um quiz de exemplo com 10 questões (astronomia básica), das quais 7 em 2 etapas: a resposta (escolha
-- única ou verdadeiro ou falso) e o porquê, entre 3 alternativas. Em 3 delas o autor ligou o meio ponto (só a resposta
-- certa vale 0,5). As outras 3 são dos formatos da US58, para mostrar a questão nova junto delas. Sorteia 5 por
-- tentativa, com a nota de corte de 70%. Na demo, a espera depois de reprovar é de 60 s (no produto, 10 min).
DELETE FROM poc_eq_questions WHERE quiz_id = 'porque';
DELETE FROM poc_eq_quizzes WHERE id = 'porque';
